Definition protocol_quantity_add (left' : protocol_quantity) (right' : protocol_quantity)
(*(0 <=? left') && (left' <=? (2 ^ 64 - 1))*) (*(0 <=? right') && (right' <=? (2 ^ 64 - 1))*)
