Definition protocol_quantity_quotient (value : protocol_quantity) (divisor : protocol_divisor)
(*(0 <=? value) && (value <=? (2 ^ 64 - 1))*) (*(1 <=? divisor) && (divisor <=? 256)*)
: M (protocol_quantity) :=
