    : M (byte_quantity).

Definition rlp_bytes_size (data : list (mword 8)) (len : byte_quantity) : M (byte_length) :=
   let first : mword 8 := match data with | b :: _ => b | [] => (Ox"00") end in
   (rlp_string_size (len) (first))
