   let len := rlp_minimal_word_len (w) in
   (rlp_string_size ((ByteQuantity (len)))
      ((if Z.eqb (len) (1) then word_low_byte (w)
        else (Ox"00"))))
    : M (byte_quantity).

Definition rlp_protocol_quantity_size (n : protocol_quantity) (*(0 <=? n) && (n <=? (2 ^ 64 - 1))*)
: M (byte_length) :=
