   returnM ((ByteQuantity ((uint (value))))).

Definition rlp_bytes_equal_at
(expected : list (mword 8)) (source : ByteSlice) (start : byte_quantity)
: M (bool) :=
   let rest : list (mword 8) := expected in
   let current : byte_quantity := start in
   let equal : bool := true in
   (let '(loop_byte_index_lower) := 0 in
   let '(loop_byte_index_upper) := 7 in
   (foreach_ZM_up loop_byte_index_lower loop_byte_index_upper 1 (current, equal, rest)
     (fun byte_index '(current, equal, rest) =>
       match rest with
       | b :: tail =>
          (and_boolM (returnM ((equal  : bool)))
             ((slice_byte (source) (current)) >>= fun (w__0 : mword 8) =>
              returnM (((eq_vec (w__0) (b))  : bool)))) >>= fun (w__1 : bool) =>
          let equal := w__1  : bool in
          (rlp_checked_add_quantity (current) (BYTE_ONE)) >>= fun (w__2 : byte_quantity) =>
          let current := w__2  : byte_quantity in
          let rest : list (mword 8) := tail in
          returnM ((current, equal, rest))
       | [] => returnM ((current, equal, rest))
       end
        : M ((byte_quantity * bool * list (mword 8)))))) >>= fun '((current, equal, rest)
   : (byte_quantity * bool * list (mword 8))) =>
   returnM (match rest with | [] => equal | _ => false end).

Definition rlp_ref_hdr (b : ByteSlice) (pos : byte_quantity) (stop : byte_quantity)
: M ((bool * source_pointer * byte_length)) :=
   (if negb ((byte_quantity_lt (pos) (stop))) return M (unit) then throw (InvalidBlock (RlpDecode))
    else returnM (tt)) >>
   (slice_byte (b) (pos)) >>= fun (w__0 : mword 8) =>
   let h := uint (w__0) in
   (if Z.ltb (h) (128) then returnM ((false, pos, BYTE_ONE))
    else if Z.ltb (h) (184) return M ((bool * byte_quantity * byte_quantity)) then
      (rlp_checked_add_quantity (pos) (BYTE_ONE)) >>= fun (w__1 : byte_quantity) =>
      returnM ((false, w__1, ByteQuantity ((Z.sub (h) (128)))))
    else if Z.ltb (h) (192) return M ((bool * byte_quantity * byte_quantity)) then
      let length_width : Z := Z.sub (h) (183) in
      (rlp_checked_add_quantity (pos) (BYTE_ONE)) >>= fun length_start =>
      (rlp_checked_add_quantity (length_start) ((ByteQuantity (length_width)))) >>= fun content =>
      (if byte_quantity_lt (stop) (content) return M (unit) then throw (InvalidBlock (RlpDecode))
       else returnM (tt)) >>
      (rlp_ref_be_length (b) (length_start) (length_width)) >>= fun (w__2 : byte_quantity) =>
      returnM ((false, content, w__2))
    else if Z.ltb (h) (248) return M ((bool * byte_quantity * byte_quantity)) then
      (rlp_checked_add_quantity (pos) (BYTE_ONE)) >>= fun (w__3 : byte_quantity) =>
      returnM ((true, w__3, ByteQuantity ((Z.sub (h) (192)))))
    else
      let length_width : Z := Z.sub (h) (247) in
      (rlp_checked_add_quantity (pos) (BYTE_ONE)) >>= fun length_start =>
      (rlp_checked_add_quantity (length_start) ((ByteQuantity (length_width)))) >>= fun content =>
      (if byte_quantity_lt (stop) (content) return M (unit) then throw (InvalidBlock (RlpDecode))
       else returnM (tt)) >>
      (rlp_ref_be_length (b) (length_start) (length_width)) >>= fun (w__4 : byte_quantity) =>
      returnM ((true, content, w__4)))
    : M ((bool * byte_quantity * byte_quantity)).

Definition rlp_field_ref
(source : ByteSlice) (is_list : bool) (full_off : byte_quantity) (full_len : byte_quantity)
(content_off : byte_quantity) (content_len : byte_quantity)
: RlpFieldRef :=
   {| RlpFieldRef_source := source;
      RlpFieldRef_is_list := is_list;
      RlpFieldRef_full_off := full_off;
      RlpFieldRef_full_len := full_len;
      RlpFieldRef_content_off := content_off;
      RlpFieldRef_content_len := content_len |}.

Definition rlp_invalid_cursor (source : ByteSlice) : RlpCursor :=
   {| RlpCursor_source := source;
      RlpCursor_current := BYTE_ZERO;
      RlpCursor_stop := BYTE_ZERO;
      RlpCursor_valid := false |}.

Definition rlp_node_cursor (node : ByteSlice) : M (RlpCursor) :=
   let n := node.(ByteSlice_len) in
   (if generic_eq (n) (BYTE_ZERO) then returnM ((rlp_invalid_cursor (node)))
    else
      (rlp_ref_hdr (node) (BYTE_ZERO) (n)) >>= fun '((is_list, content, content_len)) =>
      (rlp_checked_add_quantity (content) (content_len)) >>= fun content_stop =>
      returnM ((if andb (is_list) ((generic_eq (content_stop) (n))) then
                  {| RlpCursor_source := node;
                     RlpCursor_current := content;
                     RlpCursor_stop := content_stop;
                     RlpCursor_valid := true |}
