Definition branch_children_get (children : vec RlpFieldRef 16) (index : mword 4) : RlpFieldRef :=
   let p0_ := index in
   if eq_vec (p0_) ((Ox"0")) then vec_access_dec (children) (0)
   else if eq_vec (p0_) ((Ox"1")) then vec_access_dec (children) (1)
   else if eq_vec (p0_) ((Ox"2")) then vec_access_dec (children) (2)
   else if eq_vec (p0_) ((Ox"3")) then vec_access_dec (children) (3)
   else if eq_vec (p0_) ((Ox"4")) then vec_access_dec (children) (4)
   else if eq_vec (p0_) ((Ox"5")) then vec_access_dec (children) (5)
   else if eq_vec (p0_) ((Ox"6")) then vec_access_dec (children) (6)
   else if eq_vec (p0_) ((Ox"7")) then vec_access_dec (children) (7)
   else if eq_vec (p0_) ((Ox"8")) then vec_access_dec (children) (8)
   else if eq_vec (p0_) ((Ox"9")) then vec_access_dec (children) (9)
   else if eq_vec (p0_) ((Ox"A")) then vec_access_dec (children) (10)
   else if eq_vec (p0_) ((Ox"B")) then vec_access_dec (children) (11)
   else if eq_vec (p0_) ((Ox"C")) then vec_access_dec (children) (12)
   else if eq_vec (p0_) ((Ox"D")) then vec_access_dec (children) (13)
   else if eq_vec (p0_) ((Ox"E")) then vec_access_dec (children) (14)
   else vec_access_dec (children) (15).

Definition path_byte_index (i : trie_path_cursor) (*(0 <=? i) && (i <=? 64)*) : M (b256_index) :=
   let i := (i).(trie_path_cursor_value) in
   (let quotient := Z.quot (i) (2) in
   (if andb ((Z.leb (0) (quotient))) ((Z.leb (quotient) (31))) then returnM (quotient)
    else assert_exp' false "sail/lib/mpt/primitives.sail:64.24-64.25" >>= fun _ => exit tt) >>= fun (natural_index : Z) =>
   returnM ((Z.sub (31) (natural_index)))) >>= fun semanticResult =>
   returnM (Build_b256_index (semanticResult)).

Definition path_len (path : TriePath) : trie_path_len :=
