Definition path_append_nibble (path : TriePath) (value : mword 4) : M (TriePath) :=
   let length := (path_len (path)).(trie_path_len_value) in
   (if Z.leb (64) (length) return M (unit) then throw (InvalidBlock (WitnessDeficient))
    else returnM (tt)) >>
