              returnM (semanticResult).(trie_path_len_value)) >>= fun (w__2 : Z) =>
             let index := w__2  : Z in
             returnM ((index, result))
           else returnM ((index, result)))
           : M ((Z * TriePath))))) >>= fun '((index, result)
      : (Z * TriePath)) =>
