    else throw (InvalidBlock (WitnessDeficient)))
    : M (TriePath).

Definition path_empty '(tt : unit) : TriePath :=
   path_new ((b256_zero (tt))) (Build_trie_path_len ((0))).

Definition path_single (n : mword 4) : M (TriePath) :=
   (path_append_nibble ((path_empty (tt))) (n))  : M (TriePath).

Definition HEX_PREFIX_MAX_LENGTH : byte_length := ByteQuantity (33).
#[export] Hint Unfold HEX_PREFIX_MAX_LENGTH : sail.
Definition hex_prefix_decode_ref (f : RlpFieldRef) : M ((bool * TriePath)) :=
   (if f.(RlpFieldRef_is_list) return M (unit) then throw (InvalidBlock (RlpDecode))
    else returnM (tt)) >>
   let n := f.(RlpFieldRef_content_len) in
   let off := f.(RlpFieldRef_content_off) in
   (if generic_eq (n) (BYTE_ZERO) then returnM ((false, path_empty (tt)))
    else
      (if byte_quantity_lt (HEX_PREFIX_MAX_LENGTH) (n) return M (unit) then
         throw (InvalidBlock (RlpDecode))
       else returnM (tt)) >>
      (slice_byte (f.(RlpFieldRef_source)) (off)) >>= fun fb =>
      let flag : mword 4 := subrange_vec_dec (fb) (7) (4) in
      let is_leaf : bool := eq_vec ((access_vec_dec (flag) (1))) (('b"1")) in
      let odd : bool := eq_vec ((access_vec_dec (flag) (0))) (('b"1")) in
      let path := path_empty (tt) in
      (if odd return M (TriePath) then
         (path_single ((subrange_vec_dec (fb) (3) (0)))) >>= fun (w__0 : TriePath) =>
         (path_concat (path) (w__0))
          : M (TriePath)
       else returnM (path)) >>= fun (path : TriePath) =>
      let cursor : byte_quantity := BYTE_ONE in
      (let '(loop__step_lower) := 0 in
      let '(loop__step_upper) := 31 in
      (foreach_ZM_up loop__step_lower loop__step_upper 1 (cursor, path)
        (fun _step '(cursor, path) =>
          (if byte_quantity_lt (cursor) (n) return M ((byte_quantity * TriePath)) then
             (byte_quantity_add (off) (cursor)) >>= fun (w__2 : byte_quantity) =>
             (slice_byte (f.(RlpFieldRef_source)) (w__2)) >>= fun b =>
             (path_single ((subrange_vec_dec (b) (7) (4)))) >>= fun (w__3 : TriePath) =>
             (path_concat (path) (w__3)) >>= fun (w__4 : TriePath) =>
             let path := w__4  : TriePath in
             (path_single ((subrange_vec_dec (b) (3) (0)))) >>= fun (w__5 : TriePath) =>
             (path_concat (path) (w__5)) >>= fun (w__6 : TriePath) =>
             let path := w__6  : TriePath in
             (byte_quantity_add (cursor) (BYTE_ONE)) >>= fun (w__7 : byte_quantity) =>
             let cursor := w__7  : byte_quantity in
             returnM ((cursor, path))
           else returnM ((cursor, path)))
           : M ((byte_quantity * TriePath))))) >>= fun '((cursor, path)
      : (byte_quantity * TriePath)) =>
      returnM ((is_leaf, path)))
    : M ((bool * TriePath)).

Definition decode_trie_node (node : ByteSlice) : M (TrieNode) :=
   (rlp_node_cursor (node)) >>= fun fields =>
   (if orb ((negb (fields.(RlpCursor_valid)))) ((rlp_cursor_empty (fields))) then
      returnM ((InvalidNode (tt)))
    else
      (rlp_cursor_pop (fields)) >>= fun '((first, fields)) =>
      (if rlp_cursor_empty (fields) then returnM ((InvalidNode (tt)))
       else
         (rlp_cursor_pop (fields)) >>= fun '((second, fields)) =>
         (if rlp_cursor_empty (fields) return M (TrieNode) then
            let path_field := first in
            let value := second in
            (hex_prefix_decode_ref (path_field)) >>= fun '((is_leaf, path)) =>
            returnM ((if is_leaf then
                        LeafNode (({| LeafNodeData_path := path;  LeafNodeData_value := value |}))
                      else if Z.eqb (((path_len (path)).(trie_path_len_value))) (0) then
                        InvalidNode (tt)
                      else
                        ExtensionNode
                          (({| ExtensionNodeData_path := path;
                               ExtensionNodeData_child := value |}))))
          else
            let children : vec RlpFieldRef 16 := vector_init (16) (first) in
            let children : vec RlpFieldRef 16 := vec_update_dec (children) (0) (first) in
            let children : vec RlpFieldRef 16 := vec_update_dec (children) (1) (second) in
            let cursor := fields in
            let complete : bool := true in
            (let '(loop_index_lower) := 2 in
            let '(loop_index_upper) := 15 in
            (foreach_ZM_up loop_index_lower loop_index_upper 1 (children, complete, cursor)
              (fun index '(children, complete, cursor) =>
                (if rlp_cursor_empty (cursor) then
                   let complete : bool := false in
                   returnM ((children, complete, cursor))
                 else
                   (rlp_cursor_pop (cursor)) >>= fun '((child, next)) =>
                   let children : vec RlpFieldRef 16 := vec_update_dec (children) (index) (child) in
                   let cursor : RlpCursor := next in
                   returnM ((children, complete, cursor)))
                 : M ((vec RlpFieldRef 16 * bool * RlpCursor))))) >>= fun '((children, complete, cursor)
            : (vec RlpFieldRef 16 * bool * RlpCursor)) =>
            (if orb ((negb (complete))) ((rlp_cursor_empty (cursor))) then
               returnM ((InvalidNode (tt)))
             else
               (rlp_cursor_pop (cursor)) >>= fun '((value, cursor)) =>
               returnM ((if rlp_cursor_empty (cursor) then
                           BranchNode
                             (({| BranchNodeData_children := children;
                                  BranchNodeData_value := value |}))
                         else InvalidNode (tt))))
             : M (TrieNode))
          : M (TrieNode))
       : M (TrieNode))
    : M (TrieNode).

Definition MPT_HASH_LENGTH : byte_length := WORD_BYTE_LENGTH.
#[export] Hint Unfold MPT_HASH_LENGTH : sail.
Definition inline_node_from_slice (bytes : ByteSlice) : M (InlineNode) :=
   let length := bytes.(ByteSlice_len) in
   (if byte_quantity_le (MPT_HASH_LENGTH) (length) return M (unit) then
      throw (InvalidBlock (WitnessDeficient))
    else returnM (tt)) >>
   let data : mword 256 := zeros (256) in
   (let '(loop_offset_lower) := 0 in
   let '(loop_offset_upper) := 30 in
   (foreach_ZM_up loop_offset_lower loop_offset_upper 1 data
     (fun offset data =>
       let byte_offset := ByteQuantity (offset) in
       (if byte_quantity_lt (byte_offset) (length) return M (mword 256) then
          (slice_byte (bytes) (byte_offset)) >>= fun (w__0 : mword 8) =>
          let data := (or_vec ((shiftl (data) (8))) ((zero_extend (w__0) (256))))  : mword 256 in
          returnM (data)
        else returnM (data))
        : M (mword 256)))) >>= fun (data : mword 256) =>
   returnM (({| InlineNode_data := data;  InlineNode_len := length |})).

Definition field_to_ref (f : RlpFieldRef) : M (NodeRef) :=
   (if f.(RlpFieldRef_is_list) return M (NodeRef) then
      (rlp_ref_full (f)) >>= fun (w__0 : ByteSlice) =>
      (inline_node_from_slice (w__0)) >>= fun (w__1 : InlineNode) => returnM ((InlineRef (w__1)))
    else if generic_eq (f.(RlpFieldRef_content_len)) (MPT_HASH_LENGTH) return M (NodeRef) then
      (rlp_ref_word (f)) >>= fun (w__2 : word) => returnM ((HashRef ((word_to_hash (w__2)))))
    else returnM ((EmptyRef (tt))))
    : M (NodeRef).

Definition path_matches (key : TriePath) (pos : trie_path_cursor) (seg : TriePath)
(*(0 <=? pos) && (pos <=? 64)*)
: M (bool) :=
   let pos := (pos).(trie_path_cursor_value) in
   let stop := Z.add (pos) (((path_len (seg)).(trie_path_len_value))) in
   (if Z.ltb (((path_len (key)).(trie_path_len_value))) (stop) then returnM (false)
    else
      let ok : bool := true in
      let offset : Z := 0 in
      (let '(loop__step_lower) := 0 in
      let '(loop__step_upper) := 63 in
      (foreach_ZM_up loop__step_lower loop__step_upper 1 (offset, ok)
        (fun _step '(offset, ok) =>
          (if Z.ltb (offset) (((path_len (seg)).(trie_path_len_value))) return M ((Z * bool)) then
             let key_index := Z.add (pos) (offset) in
             (if Z.leb (key_index) (64) return M (bool) then
                (path_nibble (key) (Build_trie_path_cursor ((key_index)))) >>= fun (w__0 : mword 4) =>
                (path_nibble (seg) (Build_trie_path_cursor ((offset)))) >>= fun (w__1 : mword 4) =>
                let ok : bool := if neq_vec (w__0) (w__1) then false else ok in
                returnM (ok)
              else returnM (false)) >>= fun (ok : bool) =>
             ((trie_path_len_increment (Build_trie_path_len ((offset)))) >>= fun semanticResult =>
              returnM (semanticResult).(trie_path_len_value)) >>= fun (w__2 : Z) =>
             let offset := w__2  : Z in
             returnM ((offset, ok))
           else returnM ((offset, ok)))
           : M ((Z * bool))))) >>= fun '((offset, ok)
      : (Z * bool)) =>
      returnM (ok))
    : M (bool).

Definition inline_node_to_list (node : InlineNode) : list byte :=
   let bytes : list (mword 8) := [] in
   let data : mword 256 := node.(InlineNode_data) in
   let '((bytes, data)) :=
     (let '(loop_index_lower) := 0 in
     let '(loop_index_upper) := 30 in
     (foreach_Z_up loop_index_lower loop_index_upper 1 (bytes, data)
       (fun index '(bytes, data) =>
         let '((bytes, data)) :=
           (if byte_quantity_lt ((ByteQuantity (index))) (node.(InlineNode_len)) then
              let bytes : list (mword 8) := (subrange_vec_dec (data) (7) (0)) :: bytes in
              let data : mword 256 := shiftr (data) (8) in
              (bytes, data)
            else (bytes, data))
            : (list (mword 8) * mword 256) in
         (bytes, data))))
      : (list (mword 8) * mword 256) in
   bytes.

Definition inline_node_slice (node : InlineNode) : M (ByteSlice) :=
   (scratch_begin (tt)) >>= fun start =>
   (scratch_push_bytes ((inline_node_to_list (node))) (node.(InlineNode_len))) >>
   (scratch_finish (start))
    : M (ByteSlice).

Definition resolve_ref (r : NodeRef) : M (ByteSlice) :=
   match r with
   | EmptyRef tt => returnM (EMPTY_SLICE)
   | InlineRef node => (inline_node_slice (node))  : M (ByteSlice)
   | HashRef h =>
      (node_db_lookup (h)) >>= fun node =>
      (if generic_eq (node.(ByteSlice_len)) (BYTE_ZERO) return M (ByteSlice) then
         throw (InvalidBlock (WitnessDeficient))
       else returnM (node))
       : M (ByteSlice)
   end
    : M (ByteSlice).

Fixpoint _rec_trie_walk (node : ByteSlice) (key : TriePath) (pos : trie_path_cursor) (_reclimit : Z)
(*(0 <=? pos) && (pos <=? 64)*) (_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (ByteSlice).
exact (
   let pos := (pos).(trie_path_cursor_value) in
   assert_exp' (Z.geb (_reclimit) (0)) "recursion limit reached" >>= fun _ =>
   (if generic_eq (node.(ByteSlice_len)) (BYTE_ZERO) then returnM (EMPTY_SLICE)
    else
      (decode_trie_node (node)) >>= fun (w__0 : TrieNode) =>
      match w__0 with
      | LeafNode leaf =>
         (path_matches (key) (Build_trie_path_cursor ((pos))) (leaf.(LeafNodeData_path))) >>= fun (w__1 : bool) =>
         (if negb (w__1) then returnM (EMPTY_SLICE)
          else if Z.eqb
                    ((Z.add (pos) (((path_len (leaf.(LeafNodeData_path))).(trie_path_len_value)))))
                    (((path_len (key)).(trie_path_len_value)))
            return
            M (ByteSlice) then
            (rlp_ref_content (leaf.(LeafNodeData_value)))
             : M (ByteSlice)
          else returnM (EMPTY_SLICE))
          : M (ByteSlice)
      | ExtensionNode ext =>
         let extension_len : Z := (path_len (ext.(ExtensionNodeData_path))).(trie_path_len_value) in
         (if Z.eqb (extension_len) (0) then returnM (EMPTY_SLICE)
          else
            (path_matches (key) (Build_trie_path_cursor ((pos))) (ext.(ExtensionNodeData_path))) >>= fun (w__5 : bool) =>
            (if negb (w__5) then returnM (EMPTY_SLICE)
             else
               let next_pos := Z.add (pos) (extension_len) in
               (if Z.leb (next_pos) (64) return M (ByteSlice) then
                  (field_to_ref (ext.(ExtensionNodeData_child))) >>= fun (w__6 : NodeRef) =>
                  (resolve_ref (w__6)) >>= fun (w__7 : ByteSlice) =>
                  (_rec_trie_walk (w__7) (key) (Build_trie_path_cursor ((next_pos)))
                     ((Z.sub (_reclimit) (1))) (_limit_reduces_bool _acc ltac:(assumption)))
                   : M (ByteSlice)
                else returnM (EMPTY_SLICE))
                : M (ByteSlice))
             : M (ByteSlice))
          : M (ByteSlice)
      | BranchNode branch =>
         (if Z.eqb (pos) (((path_len (key)).(trie_path_len_value))) return M (ByteSlice) then
            (rlp_ref_content (branch.(BranchNodeData_value)))
             : M (ByteSlice)
          else if Z.ltb (pos) (((path_len (key)).(trie_path_len_value))) return M (ByteSlice) then
            (path_nibble (key) (Build_trie_path_cursor ((pos)))) >>= fun (w__13 : mword 4) =>
            (field_to_ref ((branch_children_get (branch.(BranchNodeData_children)) (w__13)))) >>= fun (w__14 : NodeRef) =>
            (resolve_ref (w__14)) >>= fun child =>
            (_rec_trie_walk (child) (key) (Build_trie_path_cursor (((Z.add (pos) (1)))))
               ((Z.sub (_reclimit) (1))) (_limit_reduces_bool _acc ltac:(assumption)))
             : M (ByteSlice)
          else returnM (EMPTY_SLICE))
          : M (ByteSlice)
      | InvalidNode tt => returnM (EMPTY_SLICE)
      end
       : M (ByteSlice))
    : M (ByteSlice)
).
Defined.


Definition trie_walk (node : ByteSlice) (key : TriePath) (pos : trie_path_cursor)
(*(0 <=? pos) && (pos <=? 64)*)
: M (ByteSlice) :=
   let pos := (pos).(trie_path_cursor_value) in
   (_rec_trie_walk (node) (key) (Build_trie_path_cursor ((pos))) (((Z.sub (64) (pos))  : Z))
      (Zwf_guarded _))
    : M (ByteSlice).

Definition trie_lookup (root : b256) (key : TriePath) : M (ByteSlice) :=
   (if generic_eq (root) (EMPTY_TRIE_ROOT) then returnM (EMPTY_SLICE)
    else
      (node_db_lookup (root)) >>= fun node =>
      (if generic_eq (node.(ByteSlice_len)) (BYTE_ZERO) return M (ByteSlice) then
         throw (InvalidBlock (WitnessDeficient))
       else (trie_walk (node) (key) (Build_trie_path_cursor ((0))))  : M (ByteSlice))
       : M (ByteSlice))
    : M (ByteSlice).

Definition stateless_account (root : b256) (a : address_typ) : M (option AccountInfo) :=
   (keccak256_address (a)) >>= fun (w__0 : b256) =>
   (trie_lookup (root) ((path_from_hash (w__0)))) >>= fun value =>
   (if generic_eq (value.(ByteSlice_len)) (BYTE_ZERO) then returnM (None)
    else (decode_state_account (value)) >>= fun (w__1 : AccountInfo) => returnM ((Some (w__1))))
    : M (option AccountInfo).

Definition k_aload (a : address_typ) : M (Account) :=
   catch_early_return
     (liftR ((bal_account_touch (a))) >>
     liftR ((acct_tx_get (a))) >>= fun (w__0 : option Account) =>
     match w__0 with
     | Some acc => (early_return (acc  : Account) : MR Account unit)  : MR (Account) (unit)
     | None => returnR (Account) (tt)
     end >>
     liftR ((acct_block_get (a))) >>= fun (w__1 : option Account) =>
     match w__1 with
     | Some acc => (early_return (acc  : Account) : MR Account unit)  : MR (Account) (unit)
     | None => returnR (Account) (tt)
     end >>
     liftR (read_reg k_parent_state_root) >>= fun (w__2 : b256) =>
     liftR ((stateless_account (w__2) (a))) >>= fun (w__3 : option AccountInfo) =>
     let acc : Account :=
       match w__3 with | Some info => account_from_info (info) | None => EMPTY_ACCOUNT end in
     liftR ((acct_block_cache (a) (acc))) >> returnR (Account) (acc)).

Definition stateless_storage (root : b256) (slot : word) : M (word) :=
   (keccak256_word (slot)) >>= fun (w__0 : b256) =>
   (trie_lookup (root) ((path_from_hash (w__0)))) >>= fun value =>
   (if generic_eq (value.(ByteSlice_len)) (BYTE_ZERO) then returnM (ZERO_WORD)
    else
