    : M (word).

Definition k_sload (a : address_typ) (s : word) : M (StorageValue) :=
   catch_early_return
     (liftR ((bal_storage_read (a) (s))) >>
     let key := storage_key (a) (s) in
     liftR ((storage_tx_get (key))) >>= fun (w__0 : option StorageValue) =>
     match w__0 with
     | Some e =>
        (early_return (e  : StorageValue) : MR StorageValue unit)  : MR (StorageValue) (unit)
     | None => returnR (StorageValue) (tt)
     end >>
