Definition suspend_frame '(tt : unit) : M (FrameCheckpoint) :=
   (k_state_checkpoint (tt)) >>= fun state =>
   read_reg pc >>= fun saved_pc =>
   read_reg gas_remaining >>= fun saved_gas =>
   read_reg frame_refund >>= fun saved_refund =>
   read_reg frame_status >>= fun saved_status =>
   read_reg message >>= fun saved_message =>
   read_reg call_depth >>= fun saved_depth =>
   read_reg frame_code >>= fun saved_code =>
   read_reg calldata >>= fun saved_calldata =>
   (stack_enter_frame (tt)) >>
   (memory_frame_enter (tt)) >>= fun saved_memory =>
   returnM (({| FrameCheckpoint_state := state;
                FrameCheckpoint_pc := saved_pc;
                FrameCheckpoint_gas_remaining := saved_gas;
                FrameCheckpoint_refund := saved_refund;
                FrameCheckpoint_status := saved_status;
                FrameCheckpoint_message := saved_message;
                FrameCheckpoint_call_depth := (Build_frame_depth (saved_depth));
                FrameCheckpoint_code := saved_code;
                FrameCheckpoint_calldata := saved_calldata;
                FrameCheckpoint_memory := saved_memory |})).

Definition restore_frame (checkpoint : FrameCheckpoint) : M (unit) :=
   (stack_leave_frame (tt)) >>
   (memory_frame_leave (checkpoint.(FrameCheckpoint_memory))) >>
   write_reg pc checkpoint.(FrameCheckpoint_pc) >>
   write_reg gas_remaining checkpoint.(FrameCheckpoint_gas_remaining) >>
   write_reg frame_refund checkpoint.(FrameCheckpoint_refund) >>
   write_reg frame_status checkpoint.(FrameCheckpoint_status) >>
   write_reg message checkpoint.(FrameCheckpoint_message) >>
   write_reg call_depth (checkpoint.(FrameCheckpoint_call_depth)).(frame_depth_value) >>
   write_reg frame_code checkpoint.(FrameCheckpoint_code) >>
   write_reg calldata checkpoint.(FrameCheckpoint_calldata)
    : M (unit).

