Definition execute_storage (op : ast) : M (unit) :=
   match op with
   | SLOAD tt =>
      (pop (tt)) >>= fun s =>
      (self_addr (tt)) >>= fun (w__0 : address_typ) =>
      (k_slot_is_warm (w__0) (s)) >>= fun warm =>
      (charge_constant ((sload_cost (warm)))) >>
