      (if w__1 return M (unit) then
         (self_addr (tt)) >>= fun (w__2 : address_typ) =>
         (k_sload (w__2) (s)) >>= fun (w__3 : StorageValue) =>
         (push (w__3.(StorageValue_curr)))
          : M (unit)
       else returnM (tt))
       : M (unit)
