Definition execute_halt (op : ast) : M (unit) :=
   match op with
   | STOP tt => write_reg frame_status (Halted ((HaltStop (tt))))  : M (unit)
   | RETURN tt =>
      (pop (tt)) >>= fun offset_word =>
