   | CALLVALUE tt => (execute_environment (op))  : M (unit)
   | GASPRICE tt => (execute_environment (op))  : M (unit)
   | CALLDATASIZE tt => (execute_environment (op))  : M (unit)
   | CALLDATALOAD tt => (execute_environment (op))  : M (unit)
