   | CALLCODE tt => (run_call (CallCode))  : M (unit)
   | DELEGATECALL tt => (run_call (DelegateCall))  : M (unit)
   | STATICCALL tt => (run_call (StaticCall))  : M (unit)
   | _ => (execute_opcode (op))  : M (unit)
