         (k_bump_nonce (authority)) >>
         (if existed return M (gas_refund) then
            (gas_constant_sub (PER_EMPTY_ACCOUNT) (PER_AUTH_BASE)) >>= fun (w__4 : gas_cost) =>
            let refund := (gas_cost_to_refund (w__4))  : gas_refund in
            returnM (refund)
          else returnM (refund))
          : M (gas_refund)
       else returnM (refund))
       : M (gas_refund)
    else returnM (refund))
    : M (gas_refund).

Fixpoint process_auth_list (xs : list Authorization) : M (gas_refund) :=
   match xs with
   | [] => returnM (GAS_REFUND_ZERO)
   | a :: r =>
      (process_auth (a)) >>= fun (w__0 : gas_refund) =>
      (process_auth_list (r)) >>= fun (w__1 : gas_refund) =>
      returnM ((gas_refund_add (w__0) (w__1)))
