      (byte_quantity_add (bs_start) (SSZ_UINT_BYTES)) >>= fun (w__17 : byte_quantity) =>
      (byte_quantity_add (w__17) (SSZ_UINT_BYTES)) >>= fun (w__18 : byte_quantity) =>
      ((ssz_uint (cc) (w__18)) >>= fun semanticResult =>
