       returnM (semanticResult).(protocol_quantity_value))
       : M (Z)
    else throw (InvalidBlock (WitnessDeficient))) >>= fun (next_count : Z) =>
   (if gas_sum_supported (acc.(ReceiptAccumulator_cumulative_gas_used)) (receipt.(Receipt_gas_used))
      return
