Definition verify_stateless_payload (input_ref : StatelessInputRef) : M (StatelessValidationResult) :=
   let active_scope := SCOPE_DECODE_INPUT in
   (try_catch (let '(_) := (cycle_scope_start (active_scope))  : unit in
    (scratch_reset (tt)) >>
    (decode_stateless_input (input_ref)) >>= fun input =>
    write_reg k_fork input.(StatelessInput_chain_config).(ChainConfig_fork) >>
    let '(_) := (cycle_scope_end (active_scope))  : unit in
    let active_scope : mword 8 := SCOPE_INDEX_WITNESS in
    let '(_) := (cycle_scope_start (active_scope))  : unit in
    (index_execution_witness (input_ref)) >>= fun witness =>
    let '(_) := (cycle_scope_end (active_scope))  : unit in
    let active_scope : mword 8 := SCOPE_VALIDATE_PAYLOAD in
    let '(_) := (cycle_scope_start (active_scope))  : unit in
    (validate_execution_payload (input) (input_ref) (witness)) >>
    let '(_) := (cycle_scope_end (active_scope))  : unit in
    let active_scope : mword 8 := SCOPE_EXECUTE_BLOCK in
    let '(_) := (cycle_scope_start (active_scope))  : unit in
    let block := input.(StatelessInput_payload).(ExecutionPayload_block) in
    (execute_block_body (block.(Block_body)) (input_ref.(StatelessInputRef_public_keys))
       (block.(Block_header).(BlockHeader_gas_limit))) >>= fun '((exec_ok, result)) =>
    let '(_) := (cycle_scope_end (active_scope))  : unit in
    let active_scope : mword 8 := SCOPE_VALIDATE_RESULT in
    let '(_) := (cycle_scope_start (active_scope))  : unit in
    (validate_executed_block (block) (input_ref) (exec_ok) (result)) >>
    let '(_) := (cycle_scope_end (active_scope))  : unit in
    returnM ((StatelessPayloadValid (tt)))) (fun __catch_val => match __catch_val with 
    | InvalidBlock reason =>
       let '(_) := (cycle_scope_end (active_scope))  : unit in
       returnM ((StatelessPayloadInvalid
                   (({| StatelessValidationFailure_scope := active_scope;
                        StatelessValidationFailure_reason := reason |}))))
    end))
    : M (StatelessValidationResult).

