Definition RESULT_METADATA_LENGTH : byte_length := ByteQuantity (5).
#[export] Hint Unfold RESULT_METADATA_LENGTH : sail.
Definition result_prefix (root : b256) (success : bool) : M (unit) :=
   (scratch_push_bytes ((hash_to_bytes32 (root))) (WORD_BYTE_LENGTH)) >>
   (scratch_push_bytes
      ([if success then (Ox"01")
      else (Ox"00");
      (Ox"25");
      (Ox"00");
      (Ox"00");
      (Ox"00")]) (RESULT_METADATA_LENGTH))
    : M (unit).

Definition commit_validation_result (root : b256) (success : bool) (chain_config : ByteSlice)
: M (unit) :=
   (scratch_begin (tt)) >>= fun start =>
   (result_prefix (root) (success)) >>
   (scratch_push_slice (chain_config)) >>
   (scratch_finish (start)) >>= fun (w__0 : ByteSlice) =>
   (public_output_write (w__0)) >>= fun (w__1 : bool) =>
   (assert_exp w__1 "public output write")
    : M (unit).

Definition write_validation_result (input_ref : StatelessInputRef) (success : bool) : M (unit) :=
   let '(_) := (cycle_scope_start (SCOPE_COMPUTE_OUTPUT_ROOT))  : unit in
   (htr_new_payload_request (input_ref)) >>= fun root =>
   let '(_) := (cycle_scope_end (SCOPE_COMPUTE_OUTPUT_ROOT))  : unit in
   let '(_) := (cycle_scope_start (SCOPE_SERIALIZE_OUTPUT))  : unit in
   (commit_validation_result (root) (success) (input_ref.(StatelessInputRef_chain_config))) >>
   returnM ((cycle_scope_end (SCOPE_SERIALIZE_OUTPUT))).

Definition write_invalid_result '(tt : unit) : M (unit) :=
   let '(_) := (cycle_scope_start (SCOPE_SERIALIZE_OUTPUT))  : unit in
   (scratch_begin (tt)) >>= fun start =>
   (let '(loop_i_lower) := 0 in
   let '(loop_i_upper) := 35 in
   (foreach_ZM_up loop_i_lower loop_i_upper 1 tt
     (fun i _ =>
       let l__0 := i in
       let b : mword 8 :=
         if Z.eqb (l__0) (8) then (Ox"0C")
         else if Z.eqb (l__0) (20) then (Ox"10")
         else if Z.eqb (l__0) (24) then (Ox"18")
         else if Z.eqb (l__0) (28) then (Ox"08")
         else if Z.eqb (l__0) (32) then (Ox"08")
         else (Ox"00") in
       (scratch_push_bytes ([b]) (BYTE_ONE))
        : M (unit)))) >>
   (scratch_finish (start)) >>= fun chain_config =>
   (commit_validation_result (ZERO_HASH) (false) (chain_config)) >>
   returnM ((cycle_scope_end (SCOPE_SERIALIZE_OUTPUT))).

Definition main '(tt : unit) : M (unit) :=
   let '(_) := (validation_debug_reset (tt))  : unit in
   let '(_) := (cycle_scope_start (SCOPE_STATELESS_VALIDATION))  : unit in
   (try_catch ((stateless_input (tt)) >>= fun (w__0 : ByteSlice) =>
               (decode_stateless_input_ref (w__0)) >>= fun input_ref =>
               (verify_stateless_payload (input_ref)) >>= fun (validation : StatelessValidationResult) =>
               let valid : bool :=
                 match validation with
                 | StatelessPayloadValid tt => true
                 | StatelessPayloadInvalid failure =>
                    let '(_) :=
                      (validation_debug_record (failure.(StatelessValidationFailure_scope))
                         (failure.(StatelessValidationFailure_reason)))
                       : unit in
                    false
                 end in
               returnM ((Some
                           (({| GuestValidation_input_ref := input_ref;
                                GuestValidation_valid := valid |}))))) (fun __catch_val => match __catch_val with 
    | InvalidBlock reason =>
       let '(_) := (validation_debug_record (SCOPE_DECODE_INPUT) (reason))  : unit in
       returnM (None)
    end)) >>= fun (result : option GuestValidation) =>
   let '(_) := (cycle_scope_end (SCOPE_STATELESS_VALIDATION))  : unit in
   match result with
   | Some result =>
      (write_validation_result (result.(GuestValidation_input_ref)) (result.(GuestValidation_valid)))
       : M (unit)
   | None => (write_invalid_result (tt))  : M (unit)
   end
    : M (unit).

Definition initialize_registers '(tt : unit) : unit := tt.

Definition sail_model_init (_ : unit) : M (unit) :=
   write_reg scratch_cursor BYTE_ZERO >>
   write_reg k_parent_state_root ZERO_HASH >>
   write_reg k_n_headers 0 >>
   write_reg k_chain_id 1 >>
   write_reg k_fork Amsterdam >>
   write_reg
     k_blob_schedule
     ({| BlobSchedule_target := (Build_protocol_quantity (14));
         BlobSchedule_max := (Build_protocol_quantity (21));
         BlobSchedule_base_fee_update_fraction := (Build_protocol_quantity (11684671)) |}) >>
   write_reg
     k_header
     ({| BlockHeader_number := (Build_protocol_quantity (0));
         BlockHeader_timestamp := (Build_protocol_quantity (0));
         BlockHeader_extra_data := EMPTY_SLICE;
         BlockHeader_gas_limit := GAS_ZERO;
         BlockHeader_gas_used := GAS_ZERO;
         BlockHeader_prev_randao := ZERO_WORD;
         BlockHeader_base_fee := ZERO_WORD;
         BlockHeader_blob_gas_used := (Build_protocol_quantity (0));
         BlockHeader_excess_blob_gas := (Build_protocol_quantity (0));
         BlockHeader_state_root := ZERO_HASH;
         BlockHeader_receipts_root := ZERO_HASH;
         BlockHeader_logs_bloom := EMPTY_LOGS_BLOOM;
         BlockHeader_fee_recipient := ZERO_ADDR;
         BlockHeader_parent_hash := ZERO_HASH;
         BlockHeader_parent_beacon_block_root := ZERO_HASH;
         BlockHeader_slot_number := (Build_protocol_quantity (0)) |}) >>
   write_reg
     k_tx
     ({| TxEnv_origin := ZERO_ADDR;
         TxEnv_gas_price := ZERO_WORD;
         TxEnv_blob_hashes := EMPTY_BLOB_HASHES |}) >>
   write_reg pc BYTE_ZERO >>
   write_reg gas_remaining GAS_ZERO >>
   write_reg frame_refund GAS_REFUND_ZERO >>
   write_reg frame_status (Running (tt)) >>
   write_reg message DEFAULT_MESSAGE >>
   write_reg call_depth 0 >>
   write_reg frame_stack (vector_init (1024) (DEFAULT_FRAME_CONTINUATION)) >>
   write_reg frame_stack_top 0 >>
   write_reg frame_code EMPTY_CODE >>
   write_reg calldata EMPTY_SLICE >>
   write_reg returndata EMPTY_SLICE >>
   write_reg evm_memory (byte_slice (EvmMemorySource) (BYTE_ZERO) (BYTE_ZERO)) >>
   returnM ((initialize_registers (tt))).



